const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.0589, 42.3601]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-05';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('ECMWF/ERA5-LAND/DAILY_AGGR')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('temperature_2m_max');

  // Check for empty collection
  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Evidence: No images found for the specified date range and location.');
    console.log('C1');
    return;
  }
  console.log(`Image collection size: ${collectionSize}`);

  // 3. Processing
  // Find the maximum and minimum temperatures over the period
  const maxTempImage = collection.max();
  const minTempImage = collection.min();

  // Define a reducer to get the value at the point
  const reducer = ee.Reducer.first();
  const scale = 1000; // Scale for ERA5-Land

  // 4. Calculation
  const maxTempK = maxTempImage.reduceRegion({
    reducer: reducer,
    geometry: boston,
    scale: scale,
    maxPixels: 1e9
  }).get('temperature_2m_max');

  const minTempK = minTempImage.reduceRegion({
    reducer: reducer,
    geometry: boston,
    scale: scale,
    maxPixels: 1e9
  }).get('temperature_2m_max');

  // Use ee.Algorithms.If to handle potential nulls on the server side
  const result = ee.Dictionary({
      max: maxTempK,
      min: minTempK
  });

  const resultInfo = result.getInfo();

  // 5. Validation & Final Answer
  if (resultInfo.max === null || resultInfo.min === null) {
      console.log('Evidence: Could not extract temperature data for the location.');
      console.log('C3');
      return;
  }

  const maxTempC = resultInfo.max - 273.15;
  const minTempC = resultInfo.min - 273.15;
  const tempDifference = maxTempC - minTempC;

  console.log(`Highest temperature (C): ${maxTempC.toFixed(2)}`);
  console.log(`Lowest temperature (C): ${minTempC.toFixed(2)}`);
  console.log(`Temperature difference (C): ${tempDifference.toFixed(2)}`);

  if (tempDifference >= 30) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
